#include <git2.h>
#include <stdio.h>
int turtlegit_http_configuration(const char *url,char ***headers,size_t *count,char **proxy){*headers=NULL;*count=0;*proxy=NULL;return 0;}
static int updated(const char *name,const git_oid *old,const git_oid *next,void *data){char a[GIT_OID_HEXSZ+1],b[GIT_OID_HEXSZ+1];git_oid_tostr(a,sizeof(a),old);git_oid_tostr(b,sizeof(b),next);printf("EVENT %s %s %s\n",name,a,b);return 0;}
int main(int argc,char **argv){git_libgit2_init();git_repository *repo=NULL;git_remote *remote=NULL;int r=git_repository_open(&repo,argv[1]);if(r<0)return 2;r=git_remote_lookup(&remote,repo,"origin");if(r<0)return 3;git_strarray before={0},after={0};git_remote_get_fetch_refspecs(&before,remote);printf("LOADED_BEFORE %zu\n",before.count);for(size_t i=0;i<before.count;i++)printf("SPEC %s\n",before.strings[i]);r=git_remote_add_fetch(repo,git_remote_name(remote),argv[2]);printf("ADD_RESULT %d\n",r);git_remote_get_fetch_refspecs(&after,remote);printf("LOADED_AFTER %zu\n",after.count);for(size_t i=0;i<after.count;i++)printf("SPEC_AFTER %s\n",after.strings[i]);git_fetch_options opts=GIT_FETCH_OPTIONS_INIT;opts.callbacks.update_tips=updated;opts.update_fetchhead=GIT_REMOTE_UPDATE_FETCHHEAD|GIT_REMOTE_UPDATE_REPORT_UNCHANGED;r=git_remote_fetch(remote,NULL,&opts,NULL);printf("FETCH_RESULT %d\n",r);if(r<0&&git_error_last())printf("ERROR %s\n",git_error_last()->message);git_strarray_dispose(&before);git_strarray_dispose(&after);git_remote_free(remote);git_repository_free(repo);git_libgit2_shutdown();return r<0?1:0;}
